import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";

export default function Dashboard() {
    const [error, setError] = useState("");
    const { currentUser, logout } = useAuth();
    const navigate = useNavigate();

    async function handleLogout() {
        setError("");

        try {
            await logout();
            navigate("/login");
        } catch {
            setError("Failed to log out");
        }
    }

    return (
        <div className="auth-container">
            <h2 className="auth-title">Dashboard</h2>
            {error && <div className="error-msg">{error}</div>}
            <div className="form-group" style={{ marginBottom: "1rem" }}>
                <p>
                    <strong>Email:</strong> {currentUser.email}
                </p>
                <p>
                    <strong>Status:</strong>{" "}
                    {currentUser.emailVerified ? "Verified ✅" : "Not Verified ❌"}
                </p>
            </div>
            <Link to="/update-profile" className="btn-primary" style={{ display: "block", textAlign: "center", textDecoration: "none", marginBottom: "1rem" }}>
                Update Profile (Placeholder)
            </Link>
            <button onClick={handleLogout} className="btn-primary" style={{ width: "100%", backgroundColor: "#555" }}>
                Log Out
            </button>
        </div>
    );
}
